        // Override the default aria-describedby set by jquery validator 
        // Use the custom ID we set in our HTML validation messages (e.g. 'valSelectedVehicleType')
        (function ($) {
            if (!$) return;

            function preserveARIA(scope) {
                $(scope).find('select, input, textarea').each(function () {
                    const $el = $(this);
                     
                    if (!$el.attr('data-preserve-describedby')) {
                        const initial = $el.attr('aria-describedby');
                        if (initial) {
                            $el.attr('data-preserve-describedby', initial);
                        }
                    }

                    const preserved = $el.attr('data-preserve-describedby');
                    if (!preserved) return;

                    const validIds = preserved
                        .split(/\s+/)
                        .filter(Boolean)
                        .filter((id, index, arr) => arr.indexOf(id) === index)
                        .filter(id => document.getElementById(id));

                    if (validIds.length) {
                        $el.attr('aria-describedby', validIds.join(' '));
                    } else {
                        $el.removeAttr('aria-describedby');
                    }
                });
            }

            $(function () {
                preserveARIA(document);

                $('form').on('change blur submit', 'select, input, textarea', function () {
                    const form = this.form || document;
                    setTimeout(function () {
                        preserveARIA(form);
                    }, 3000);
                });
            });
        })(jQuery);

