    const getStoredTheme = () => localStorage.getItem('theme');
    const setStoredTheme = theme => localStorage.setItem('theme', theme);

    // added for accessibility and reader
    const status  = document.getElementById("themeStatus");

    const getPreferredTheme = () => {
        const storedTheme = getStoredTheme();
        if (storedTheme) {
            return storedTheme;
        }
        // status.textContent = dark ? "Dark mode." : "Light mode.";
        return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }

    const setTheme = theme => {
        if (theme === 'auto') {
            document.documentElement.setAttribute('data-bs-theme', (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'));
        } else {
            document.documentElement.setAttribute('data-bs-theme', theme);
        }
    }

    const showActiveTheme2 = (theme, focus = false) => {

        const themeSwitcher = document.querySelector('#bd-theme-switch');

        if (!themeSwitcher) {
            return;
        }

        if (theme === "dark") {
            $("#bd-theme-switch").prop("checked", false);
            $("#lb-light").hide();
            $("#lb-dark").show();
        }
        else {
            $("#bd-theme-switch").prop("checked", true);
            $("#lb-light").show();
            $("#lb-dark").hide();
        }

        if (focus) {
            themeSwitcher.focus();
        }
    }

    //setTheme(getPreferredTheme());

    var theme = getPreferredTheme();
    setTheme(theme);
    showActiveTheme2(theme);
    setStoredTheme(theme);

    function updateTheme() {
        let theme = getStoredTheme();

        if (theme === "dark") {
            document.getElementById("imgFooterInlineMap").src = "/Images/inline-map-night.png";
            document.getElementById("imgFooterSeal").classList.add("night-outline");
            document.getElementById("imgFootorDMV").classList.add("night-outline");
            document.getElementById("imgNavBranding").classList.add("night-outline");
        } else {
            document.getElementById("imgFooterInlineMap").src = "/Images/inline-map.png";
            document.getElementById("imgFooterSeal").classList.remove("night-outline");
            document.getElementById("imgFootorDMV").classList.remove("night-outline");
            document.getElementById("imgNavBranding").classList.remove("night-outline");
        }
    }

